<script setup lang="ts">
import {ref} from 'vue';import {onLoad,onShow} from '@dcloudio/uni-app';import {useI18n} from 'vue-i18n';import {api} from '@/api';import {managementGo} from '@/shared/management';import type {OperatingContext} from '@/api/management-types';import BrandChangeSheet from '../brand-detail/components/BrandChangeSheet.vue';
const {t}=useI18n();const m=ref(''),s=ref('');const context=ref<OperatingContext|null>(null);const failed=ref(false),choosing=ref(false);
async function load(){failed.value=false;try{context.value=await api.mStoreOperatingContext(s.value,m.value)}catch{failed.value=true}}
onLoad(q=>{m.value=q?.m||'';s.value=q?.s||''});onShow(load);
</script>
<template><sh-scaffold title-key="management.storeBrand"><view v-if="failed" class="sh-card" @tap="load">{{t('management.retry')}}</view><template v-if="context"><view class="sh-card"><text class="txt-title">{{context.name}}</text><sh-kv :label="t('management.brand')">{{context.brand?.name||t('management.noBrand')}}</sh-kv><sh-kv :label="t('management.brandStoredValue')">{{t('management.notEnabled')}}</sh-kv></view><view v-if="(context.actions.includes('sv.issuer.read')||context.actions.includes('sv.issuer.prepare'))" role="button" class="sh-card sh-row sh-row--between sh-hit" @tap="managementGo('storedValueIssuer',{m:m,s:s,prepare:context.actions.includes('sv.issuer.prepare')?'1':undefined})"><text>{{t('issuer.title')}}</text><sh-go/></view><view v-if="context.pendingChange" class="sh-card sh-row sh-row--between" @tap="managementGo('brand_change',{c:context.pendingChange.changeNo})"><text>{{t('management.state.'+context.pendingChange.status)}}</text><sh-go/></view><sh-actionbar v-if="context.actions.includes('store.brand.change')"><view class="sh-btn" @tap="choosing=true">{{t('management.configureBrand')}}</view></sh-actionbar><BrandChangeSheet :visible="choosing" :management-no="m" :store-no="s" :current-brand-no="context.brand?.brandNo" :current-financial="!!context.brand?.storedValueStatus&&context.brand.storedValueStatus!=='NONE'" @close="choosing=false" @changed="load" @pending="changeNo=>managementGo('brand_change',{c:changeNo})"/></template></sh-scaffold></template>
